#import "../../../template.typ": *
#import "../support.typ": *

#let slide_05() = slide[
  #slide-head("05", [Suspension Requires Encoder-Owned State])

  #v(0.45em)

  #grid(
    columns: (1fr, 1fr),
    gutter: 6pt,
  )[
    #chip([a415231 Make async encode state encoder-owned], fill: green-soft, accent: green, size: 7pt)
  ][
    #chip([617cd50 Split encoder async state], fill: green-soft, accent: green, size: 7pt)
  ]

  #v(0.5em)

  #thesis([Any state surviving `Pending` must be owned by the encode operation.], fill: green-soft, accent: green, size: 10.4pt)

  #v(0.55em)

  #grid(columns: (1fr, auto, 1fr), gutter: 8pt, align: horizon)[
    #soft-card([Before], [
      #align(center)[#text(size: 10pt, weight: "bold", fill: orange)[driver owns too much temporary state]]
      #v(0.35em)
      #grid(columns: (1fr,), gutter: 4pt)[
        #flow-step([body driver / stream task], fill: white, accent: gray, size: 7.6pt)
      ][
        #flow-step([temporary item + dst + progress], fill: orange-soft, accent: orange, size: 7.4pt)
      ][
        #flow-step([polls encoder while retaining pieces], fill: red-soft, accent: red, size: 7.2pt)
      ]
      #v(0.25em)
      #align(center)[#text(size: 7.3pt, fill: ink-soft)[`Pending` leaves ownership split across layers.]]
    ], fill: orange-soft, accent: orange, body-size: 8pt)
  ][
    #align(center)[
      #text(size: 7.4pt, fill: palette.muted)[move the suspendable lifetime]
      #v(0.2em)
      #arrow
    ]
  ][
    #soft-card([After], [
      #align(center)[#text(size: 10pt, weight: "bold", fill: blue)[encoder future owns resumable encode state]]
      #v(0.35em)
      #grid(columns: (1fr,), gutter: 4pt)[
        #flow-step([start one owned future], fill: white, accent: blue, size: 7.6pt)
      ][
        #flow-step([future holds message + buffer + resume cursor], fill: blue-soft, accent: blue, size: 7.1pt)
      ][
        #flow-step([driver polls only the future], fill: green-soft, accent: green, size: 7.4pt)
      ]
      #v(0.25em)
      #align(center)[#text(size: 7.3pt, fill: ink-soft)[`Ready` returns the completed destination buffer.]]
    ], fill: blue-soft, accent: blue, body-size: 8pt)
  ]

  #v(0.55em)

  #soft-card([State inventory owned by the encode operation], [
    #grid(
      columns: (1fr, 1fr, 1fr),
      gutter: 5pt,
    )[
      #chip([message/item], fill: blue-soft, accent: blue)
    ][
      #chip([destination buffer], fill: blue-soft, accent: blue)
    ][
      #chip([protobuf field position], fill: violet-soft, accent: violet)
    ][
      #chip([pending payload copy], fill: orange-soft, accent: orange)
    ][
      #chip([DSA descriptor/completion], fill: red-soft, accent: red)
    ][
      #chip([retry/drop state], fill: green-soft, accent: green)
    ]
  ], fill: panel-fill, accent: blue, body-size: 7.8pt)

  #v(1fr)
  #speaker[Once encoding can suspend, “where does the state live?” becomes the API design question.]
]

#import "../../../template.typ": *
#import "../support.typ": *

#let slide_09() = slide[
  #slide-head("09", [Protobuf Resume State Must Be Exact])
  #v(0.25em)

  #thesis[Async protobuf encoding is an exact wire-format state machine: after `Pending`, resume at the byte phase already completed.]
  #v(0.45em)

  #soft-card(
    [Length-delimited payload fields have three irreversible writes],
    [
      #align(center)[#text(
        size: 7.8pt,
        weight: "semibold",
        fill: luma(70),
      )[example phase order: tag → length → payload]]
      #v(0.35em)
      #grid(columns: (1fr, auto, 1fr, auto, 1fr), gutter: 7pt, align: horizon)[
        #flow-step([tag], fill: rgb("#eef6ff"), accent: rgb("#2563eb"), size: 9pt)
      ][
        #arrow
      ][
        #flow-step([length], fill: rgb("#f5f3ff"), accent: rgb("#7c3aed"), size: 9pt)
      ][
        #arrow
      ][
        #flow-step([payload], fill: rgb("#effdf5"), accent: rgb("#16a34a"), size: 9pt)
      ]
      #v(0.55em)
      #block(
        width: 100%,
        inset: (x: 10pt, y: 6pt),
        radius: 8pt,
        fill: rgb("#fff5eb"),
        stroke: (left: 3pt + rgb("#f97316")),
      )[
        #grid(columns: (auto, 1fr), gutter: 7pt, align: horizon)[
          #chip([Pending], fill: rgb("#fff5eb"), accent: rgb("#f97316"))
        ][
          #text(
            size: 8.2pt,
            fill: luma(42),
          )[is allowed only after state records completed phases: never “maybe wrote the prefix.”]
        ]
      ]
    ],
    fill: white,
    accent: rgb("#2563eb"),
    body-size: 8.2pt,
  )
  #v(0.45em)

  #two-col(
    soft-card(
      [Resume state inventory],
      [
        #grid(columns: (1fr, 1fr), gutter: 5pt)[
          #chip([which field], fill: rgb("#eef6ff"), accent: rgb("#2563eb"))
        ][
          #chip([repeated/map index], fill: rgb("#eef6ff"), accent: rgb("#2563eb"))
        ][
          #chip([tag already written], fill: rgb("#f5f3ff"), accent: rgb("#7c3aed"))
        ][
          #chip([length prefix already written], fill: rgb("#f5f3ff"), accent: rgb("#7c3aed"))
        ][
          #chip([payload copy pending], fill: rgb("#fff5eb"), accent: rgb("#f97316"))
        ][
          #chip([nested message/oneof state active], fill: rgb("#effdf5"), accent: rgb("#16a34a"), size: 7pt)
        ]
      ],
      fill: white,
      accent: rgb("#16a34a"),
      body-size: 8pt,
    ),
    soft-card(
      [Wrong checkpoint corrupts the stream],
      [
        #warning-band[
          #grid(columns: (1fr,), gutter: 4pt)[
            #text(weight: "bold", fill: rgb("#dc2626"))[duplicate tag]
          ][
            #text(weight: "bold", fill: rgb("#dc2626"))[duplicate length prefix]
          ][
            #text(weight: "bold", fill: rgb("#dc2626"))[skipped field]
          ][
            #text(weight: "bold", fill: rgb("#dc2626"))[payload written at wrong offset]
          ][
            #text(weight: "bold", fill: rgb("#dc2626"))[invalid wire format]
          ]
        ]
      ],
      fill: rgb("#fff1f2"),
      accent: rgb("#dc2626"),
      body-size: 8pt,
    ),
    gutter: 10pt,
    ratio: (1.08fr, 0.92fr),
  )
  #v(1fr)

  #speaker[Async protobuf encoding is a resumable compiler for wire-format bytes.]
]

